def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        match = re.search(r"(?:ext|x|#)", value, re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = "".join(char for char in value if char.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        tags = [
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        ]
        opted_out = row["opted_out"].strip().lower() in {"y", "yes", "true", "1"}

        prepared.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": row["source"].strip().lower(),
            "updated": updated,
            "tags": tags,
            "opted_out": opted_out,
        })

    # Union-find makes matching transitive.
    parent = list(range(len(prepared)))

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].lower())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field, require_valid=False):
        candidates = [
            row for row in group
            if row[field] and (not require_valid or row[field])
        ]
        if not candidates:
            return ""
        candidates.sort(
            key=lambda row: (
                row["source"] != "manual",
                -row["updated"].timestamp(),
                row["index"],
            )
        )
        return candidates[0][field]

    people = []
    for group in groups.values():
        group.sort(key=lambda row: row["index"])
        latest = max(row["updated"] for row in group)
        people.append((
            group[0]["index"],
            {
                "first_name": choose(group, "first_name"),
                "last_name": choose(group, "last_name"),
                "zip": choose(group, "zip"),
                "email": choose(group, "email", require_valid=True),
                "phone": choose(group, "phone", require_valid=True),
                "source": choose(group, "source"),
                "tags": ";".join(sorted({tag for row in group for tag in row["tags"]})),
                "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
                "updated": latest.strftime("%Y-%m-%d"),
            },
        ))

    people.sort(key=lambda item: item[0])
    return [person for _, person in people]
